using System.Text.Json;
using DCode.Server.Storage;

namespace DCode.Server.Runs;

public sealed class RunRepository(DCodeDatabase database)
{
    public IReadOnlyList<RunConfiguration> ListConfigurations(string projectId){using var c=database.OpenConnection();using var q=c.CreateCommand();q.CommandText=$"SELECT {ConfigurationColumns} FROM run_configurations WHERE project_id=$project AND archived=0 ORDER BY is_detected DESC,name;";q.Parameters.AddWithValue("$project",projectId);using var r=q.ExecuteReader();var result=new List<RunConfiguration>();while(r.Read())result.Add(ReadConfiguration(r));return result;}
    public RunConfiguration GetConfiguration(string projectId,string id){using var c=database.OpenConnection();using var q=c.CreateCommand();q.CommandText=$"SELECT {ConfigurationColumns} FROM run_configurations WHERE project_id=$project AND id=$id;";q.Parameters.AddWithValue("$project",projectId);q.Parameters.AddWithValue("$id",id);using var r=q.ExecuteReader();return r.Read()?ReadConfiguration(r):throw new KeyNotFoundException("Run configuration was not found.");}
    public RunConfiguration Save(string projectId,string? id,SaveRunConfigurationRequest request,bool detected=false){var name=Required(request.Name,"Name");var command=Required(request.Command,"Command");var working=string.IsNullOrWhiteSpace(request.WorkingDirectory)?".":request.WorkingDirectory.Trim();var key=id??Guid.NewGuid().ToString("N");var now=DateTimeOffset.UtcNow.ToString("O");var arguments=request.Arguments?.Where(value=>!string.IsNullOrEmpty(value)).ToArray()??[];using var c=database.OpenConnection();using var q=c.CreateCommand();q.CommandText="""INSERT INTO run_configurations(id,project_id,name,command,arguments_json,working_directory,is_detected,created_utc,updated_utc) VALUES($id,$project,$name,$command,$arguments,$working,$detected,$now,$now) ON CONFLICT(id) DO UPDATE SET name=$name,command=$command,arguments_json=$arguments,working_directory=$working,is_detected=$detected,updated_utc=$now WHERE project_id=$project;""";Add(q,"$id",key);Add(q,"$project",projectId);Add(q,"$name",name);Add(q,"$command",command);Add(q,"$arguments",JsonSerializer.Serialize(arguments));Add(q,"$working",working);Add(q,"$detected",detected);Add(q,"$now",now);q.ExecuteNonQuery();return GetConfiguration(projectId,key);}
    public void Delete(string projectId,string id){using var c=database.OpenConnection();using var q=c.CreateCommand();q.CommandText="UPDATE run_configurations SET archived=1,updated_utc=$now WHERE id=$id AND project_id=$project AND archived=0;";Add(q,"$id",id);Add(q,"$project",projectId);Add(q,"$now",DateTimeOffset.UtcNow.ToString("O"));if(q.ExecuteNonQuery()==0)throw new KeyNotFoundException("Run configuration was not found.");}
    public RunExecution StartExecution(RunConfiguration config,string workingDirectory){var id=Guid.NewGuid().ToString("N");var now=DateTimeOffset.UtcNow.ToString("O");using var c=database.OpenConnection();using var q=c.CreateCommand();q.CommandText="INSERT INTO run_executions(id,project_id,configuration_id,status,command,arguments_json,working_directory,created_utc,started_utc,updated_utc) VALUES($id,$project,$configuration,'running',$command,$arguments,$working,$now,$now,$now);";Add(q,"$id",id);Add(q,"$project",config.ProjectId);Add(q,"$configuration",config.Id);Add(q,"$command",config.Command);Add(q,"$arguments",JsonSerializer.Serialize(config.Arguments));Add(q,"$working",workingDirectory);Add(q,"$now",now);q.ExecuteNonQuery();return GetExecution(id);}
    public void Complete(string id,string status,string stdout,string stderr,int? exitCode,string? error){var now=DateTimeOffset.UtcNow.ToString("O");using var c=database.OpenConnection();using var q=c.CreateCommand();q.CommandText="UPDATE run_executions SET status=$status,stdout=$stdout,stderr=$stderr,exit_code=$exit,error=$error,completed_utc=$now,updated_utc=$now WHERE id=$id;";Add(q,"$status",status);Add(q,"$stdout",stdout);Add(q,"$stderr",stderr);Add(q,"$exit",exitCode);Add(q,"$error",error);Add(q,"$now",now);Add(q,"$id",id);q.ExecuteNonQuery();}
    public void UpdateOutput(string id,string stdout,string stderr){using var c=database.OpenConnection();using var q=c.CreateCommand();q.CommandText="UPDATE run_executions SET stdout=$stdout,stderr=$stderr,updated_utc=$now WHERE id=$id AND status IN ('running','stopping');";Add(q,"$stdout",stdout);Add(q,"$stderr",stderr);Add(q,"$now",DateTimeOffset.UtcNow.ToString("O"));Add(q,"$id",id);q.ExecuteNonQuery();}
    public RunExecution GetExecution(string id){using var c=database.OpenConnection();using var q=c.CreateCommand();q.CommandText=$"SELECT {ExecutionColumns} FROM run_executions WHERE id=$id;";Add(q,"$id",id);using var r=q.ExecuteReader();return r.Read()?ReadExecution(r):throw new KeyNotFoundException("Run execution was not found.");}
    public IReadOnlyList<RunExecution> ListExecutions(string projectId,int limit=30){using var c=database.OpenConnection();using var q=c.CreateCommand();q.CommandText=$"SELECT {ExecutionColumns} FROM run_executions WHERE project_id=$project ORDER BY created_utc DESC LIMIT $limit;";Add(q,"$project",projectId);Add(q,"$limit",Math.Clamp(limit,1,100));using var r=q.ExecuteReader();var result=new List<RunExecution>();while(r.Read())result.Add(ReadExecution(r));return result;}
    public void MarkInterrupted(){using var c=database.OpenConnection();using var q=c.CreateCommand();q.CommandText="UPDATE run_executions SET status='interrupted',error='DCode stopped while this command was running.',completed_utc=CURRENT_TIMESTAMP,updated_utc=CURRENT_TIMESTAMP WHERE status IN ('starting','running','stopping');";q.ExecuteNonQuery();}
    private static RunConfiguration ReadConfiguration(Microsoft.Data.Sqlite.SqliteDataReader r)=>new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),JsonSerializer.Deserialize<string[]>(r.GetString(4))??[],r.GetString(5),r.GetInt32(6)==1,DateTimeOffset.Parse(r.GetString(7)),DateTimeOffset.Parse(r.GetString(8)));
    private static RunExecution ReadExecution(Microsoft.Data.Sqlite.SqliteDataReader r)=>new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),JsonSerializer.Deserialize<string[]>(r.GetString(5))??[],r.GetString(6),r.GetString(7),r.GetString(8),r.IsDBNull(9)?null:r.GetInt32(9),r.IsDBNull(10)?null:r.GetString(10),DateTimeOffset.Parse(r.GetString(11)),DateTimeOffset.Parse(r.GetString(12)),r.IsDBNull(13)?null:DateTimeOffset.Parse(r.GetString(13)),DateTimeOffset.Parse(r.GetString(14)));
    private static string Required(string? value,string name)=>string.IsNullOrWhiteSpace(value)?throw new ArgumentException($"{name} is required."):value.Trim();private static void Add(Microsoft.Data.Sqlite.SqliteCommand q,string name,object? value)=>q.Parameters.AddWithValue(name,value??DBNull.Value);
    private const string ConfigurationColumns="id,project_id,name,command,arguments_json,working_directory,is_detected,created_utc,updated_utc";
    private const string ExecutionColumns="id,project_id,configuration_id,status,command,arguments_json,working_directory,stdout,stderr,exit_code,error,created_utc,started_utc,completed_utc,updated_utc";
}
